            while (next != 0) {
                *insertion_end++ = carry;
                carry = next;
                next = *insertion_end;
                final_character = carry;
            }
            *insertion_end = final_character;
            insertion_end[1] = 0;
            ++input_length;
        }
    } else if (key == 3) {
        int cursor = input_cursor;
        if (cursor > 0) {
            char* current = &text_buffer[cursor];
            char old = *current;
            char previous = current[-1];
            *current = previous;
            current[-1] = old;
            int updated_cursor = input_cursor - 1;
            input_cursor = updated_cursor;
