        if (text_buffer[pos] == '>')
            --pos;

        if (pos != 0) {
            int next_column = 0;
            while (pos > 0) {
                if (text_buffer[pos] == '>')
                    break;
                ++next_column;
                --pos;
            }
            if (text_buffer[pos] == '>')
                ++pos;
            if (column > next_column)
                column = next_column;

            char* remove = &text_buffer[input_cursor];
            while (*remove != 0) {
                *remove = remove[1];
                ++remove;
            }

            input_cursor = pos + column;
            char* insert = &text_buffer[input_cursor];
            char carry = *insert;
            do {
                char next = insert[1];
                insert[1] = carry;
                ++insert;
                carry = next;
            } while (*insert != 0);
        }
    } else if (key == 8) {
