            char* remove = &text_buffer[cursor];
            while (*remove != 0) {
                *remove = remove[1];
                ++remove;
            }
            --input_length;
        }
    } else if (key == 2) {
        int cursor = input_cursor;
        if (cursor < input_length) {
            char* remove = &text_buffer[cursor];
            while (*remove != 0) {
                *remove = remove[1];
                ++remove;
            }
            --input_length;
        }
    } else if (key != 0) {
        if (input_length < input_capacity
            && (key != ' ' || (input_flags & 1) == 0)
            && ((input_flags & 2) == 0 || (key != ',' && key != '.'))) {
            text_buffer[input_cursor] = key;
            ++input_cursor;

            char carry = ' ';
            char next = text_buffer[input_cursor];
            char* insertion_end = &text_buffer[input_cursor];
